___CSS_LOADER_EXPORT___.push([module.id, "\n.badge[data-v-1ffc654b] {\n  padding: 5px 8px;\n  border-radius: 3px;\n  font-size: 10px;\n  font-weight: 600;\n}\n.badge-success[data-v-1ffc654b] {\n  background-color: #28a745;\n  color: white;\n}\n.badge-danger[data-v-1ffc654b] {\n  background-color: #dc3545;\n  color: white;\n}\n.table td[data-v-1ffc654b] {\n  vertical-align: middle;\n}\n", "",{"version":3,"sources":["webpack://./modules/Finance/Resources/assets/js/views/small_cash/transaction-table.vue"],"names":[],"mappings":";AAsHA;EACA,gBAAA;EACA,kBAAA;EACA,eAAA;EACA,gBAAA;AACA;AACA;EACA,yBAAA;EACA,YAAA;AACA;AACA;EACA,yBAAA;EACA,YAAA;AACA;AACA;EACA,sBAAA;AACA","sourcesContent":["<template>\n  <div class=\"table-responsive\">\n    <table class=\"table table-sm table-bordered table-hover\">\n      <thead>\n      <tr>\n        <th width=\"100\">Fecha</th>\n        <th width=\"80\">Tipo</th>\n        <th>Descripción</th>\n        <th width=\"120\">Método Pago</th>\n        <th width=\"100\">Documento</th>\n        <th width=\"150\">Proveedor/Cliente</th>\n        <th width=\"120\">Categoría</th>\n        <th width=\"100\" class=\"text-right\">Monto</th>\n        <th width=\"150\">Usuario</th>\n        <th v-if=\"editable\" width=\"120\" class=\"text-center\">Acciones</th>\n      </tr>\n      </thead>\n      <tbody v-if=\"transactions.length === 0\">\n      <tr>\n        <td :colspan=\"editable ? 10 : 9\" class=\"text-center text-muted\">\n          No hay movimientos registrados\n        </td>\n      </tr>\n      </tbody>\n      <tbody v-else>\n      <tr v-for=\"transaction in transactions\" :key=\"transaction.id\">\n        <td>{{ formatDate(transaction.date) }}</td>\n        <td>\n                        <span :class=\"getTypeClass(transaction.type)\">\n                            {{ getTypeLabel(transaction.type) }}\n                        </span>\n        </td>\n        <td>{{ transaction.description }}</td>\n        <td>\n          {{ transaction.payment_method_type ? transaction.payment_method_type.description : '-' }}\n        </td>\n        <td>{{ transaction.document_number || '-' }}</td>\n        <td>{{ transaction.supplier_customer || '-' }}</td>\n        <td>{{ transaction.category || '-' }}</td>\n        <td class=\"text-right\" :class=\"getAmountClass(transaction.type)\">\n          {{ formatMoney(transaction.amount) }}\n        </td>\n        <td>{{ transaction.user ? transaction.user.name : '-' }}</td>\n        <td v-if=\"editable\" class=\"text-center\">\n          <button\n            type=\"button\"\n            class=\"btn waves-effect waves-light btn-xs btn-info\"\n            @click=\"$emit('edit', transaction)\"\n            title=\"Editar\">\n            <i class=\"fa fa-edit\"></i>\n          </button>\n          <button\n            type=\"button\"\n            class=\"btn waves-effect waves-light btn-xs btn-danger\"\n            @click=\"$emit('delete', transaction)\"\n            title=\"Eliminar\">\n            <i class=\"fa fa-trash\"></i>\n          </button>\n        </td>\n      </tr>\n      </tbody>\n      <tfoot v-if=\"transactions.length > 0\">\n      <tr class=\"font-weight-bold bg-light\">\n        <td colspan=\"7\" class=\"text-right\">TOTAL:</td>\n        <td class=\"text-right\">{{ formatMoney(total) }}</td>\n        <td :colspan=\"editable ? 2 : 1\"></td>\n      </tr>\n      </tfoot>\n    </table>\n  </div>\n</template>\n\n<script>\nexport default {\n  name: 'TransactionTable',\n  props: {\n    transactions: {\n      type: Array,\n      required: true,\n      default: () => []\n    },\n    editable: {\n      type: Boolean,\n      default: false\n    }\n  },\n  computed: {\n    total() {\n      return this.transactions.reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);\n    }\n  },\n  methods: {\n    formatMoney(value) {\n      return new Intl.NumberFormat('es-PE', {\n        style: 'currency',\n        currency: 'PEN',\n        minimumFractionDigits: 2\n      }).format(value || 0);\n    },\n    formatDate(date) {\n      if (!date) return '-';\n      const parsedDate = moment(date, \"YYYY-MM-DD\");\n      return parsedDate.isValid() ? parsedDate.format(\"DD-MM-YYYY\") : '-';\n    },\n    getTypeClass(type) {\n      return type === 'income' ? 'badge badge-success' : 'badge badge-danger';\n    },\n    getTypeLabel(type) {\n      return type === 'income' ? 'Ingreso' : 'Egreso';\n    },\n    getAmountClass(type) {\n      return type === 'income' ? 'text-success font-weight-bold' : 'text-danger font-weight-bold';\n    }\n  }\n};\n</script>\n\n<style scoped>\n.badge {\n  padding: 5px 8px;\n  border-radius: 3px;\n  font-size: 10px;\n  font-weight: 600;\n}\n.badge-success {\n  background-color: #28a745;\n  color: white;\n}\n.badge-danger {\n  background-color: #dc3545;\n  color: white;\n}\n.table td {\n  vertical-align: middle;\n}\n</style>\n"],"sourceRoot":""}]);
